use super::*;

const SAMPLE_LOCKFILE: &str = r#"
# This file is automatically @generated by Cargo.
version = 4

[[package]]
name = "huntsman-search-engine"
version = "1.40.0"

[[package]]
name = "serde"
version = "1.0.219"
source = "registry+https://github.com/rust-lang/crates.io-index"
checksum = "5f0e2c6"

[[package]]
name = "my-git-dep"
version = "0.1.0"
source = "git+https://github.com/example/my-git-dep#abcdef"

[[package]]
name = "my-path-dep"
version = "0.1.0"
"#;

#[test]
fn keeps_only_crates_io_registry_packages() {
    let packages = crates_io_packages(SAMPLE_LOCKFILE).expect("valid lockfile");
    assert_eq!(
        packages,
        vec![RegistryPackage {
            name: "serde".to_string(),
            version: "1.0.219".to_string(),
        }]
    );
}

#[test]
fn skips_the_crate_s_own_package_entry_with_no_source() {
    let packages = crates_io_packages(SAMPLE_LOCKFILE).expect("valid lockfile");
    assert!(!packages.iter().any(|p| p.name == "huntsman-search-engine"));
}

#[test]
fn skips_git_and_path_dependencies() {
    let packages = crates_io_packages(SAMPLE_LOCKFILE).expect("valid lockfile");
    assert!(!packages.iter().any(|p| p.name == "my-git-dep"));
    assert!(!packages.iter().any(|p| p.name == "my-path-dep"));
}

#[test]
fn empty_lockfile_yields_no_packages() {
    let packages = crates_io_packages("version = 4\n").expect("valid empty lockfile");
    assert!(packages.is_empty());
}

#[test]
fn malformed_toml_is_a_parse_error() {
    assert!(crates_io_packages("not valid toml [[[").is_err());
}

#[test]
fn duplicate_versions_of_the_same_crate_both_survive() {
    let raw = r#"
[[package]]
name = "thiserror"
version = "1.0.69"
source = "registry+https://github.com/rust-lang/crates.io-index"

[[package]]
name = "thiserror"
version = "2.0.12"
source = "registry+https://github.com/rust-lang/crates.io-index"
"#;
    let packages = crates_io_packages(raw).expect("valid lockfile");
    assert_eq!(packages.len(), 2);
}
